"""Land animals of the Palaeozoic and Mesozoic: the clades that carry every
region through every age (family level, long ranges), and the genera that make a
particular place at a particular moment recognisable."""
from _lib import E, T, write
R, S, O = "Reptilia", "Saurischia", "Ornithischia"
C = ["cosmo"]
