E("Cotylorhynchus", "genus", "land", "pelycosaur", 279, 272, ["na-w", "na-e"],
  "The largest land animal of its day: a caseid with a body like a barrel and a head that looks borrowed from something a tenth its size.", cls=("Synapsida", "Pelycosauria", "Caseidae"))
# ---- insects and other land arthropods: true of everywhere, so they fill only where nothing local can
E("Odonatoptera", "superorder", "air", "dragonfly", 325, 0, C, "Dragonflies, damselflies and their giant Palaeozoic cousins the griffinflies: aerial predators for 325 million years.", hab=["wetland", "lake", "river", "forest"], w=1, cls=("Insecta", "Odonata", ""))
E("Coleoptera", "order", "land", "beetle", 295, 0, C, "Beetles. From the Permian on, the most species-rich order of animals there has ever been.", w=1, cls=("Insecta", "Coleoptera", ""))
E("Blattodea", "order", "land", "cockroach", 320, 0, C, "Cockroaches and their roachoid forerunners -- the commonest insects of the coal forests, and unhurried ever since.", hab=["forest", "rainforest", "wetland"], w=1, cls=("Insecta", "Blattodea", ""))
E("Orthoptera", "order", "land", "grasshopper", 300, 0, C, "Grasshoppers, crickets and katydids: the singing insects, and the great grazers of the insect world.", w=1, cls=("Insecta", "Orthoptera", ""))
E("Hymenoptera", "order", "air", "ant", 235, 0, C, "Sawflies first, then wasps, bees and ants. Their rise tracks the flowering plants they came to pollinate.", w=1, cls=("Insecta", "Hymenoptera", ""))
E("Formicidae", "family", "land", "ant", 100, 0, C, "Ants. Rare in Cretaceous amber, then from the Eocene on the dominant small predators and soil-movers of nearly every land habitat.", w=1, cls=("Insecta", "Hymenoptera", "Formicidae"))
E("Isoptera", "infraorder", "land", "cockroach", 130, 0, C, "Termites: social cockroaches that digest wood with the microbes in their gut, and recycle most of a tropical forest's dead timber.", lat=[0, 45], hab=["forest", "rainforest", "grassland", "desert"], w=1, cls=("Insecta", "Blattodea", "Termitidae"))
E("Lepidoptera", "order", "air", "butterfly", 200, 0, C, "Moths from the Jurassic, butterflies from the Cretaceous: scaled wings and, once flowers existed, a coiled tongue to reach nectar.", w=1, cls=("Insecta", "Lepidoptera", ""))
E("Diptera", "order", "air", "fly", 245, 0, C, "True flies -- midges, mosquitoes, hoverflies -- with the hind wings reduced to balancing knobs.", w=1, cls=("Insecta", "Diptera", ""))
E("Araneae", "order", "land", "spider", 315, 0, C, "Spiders. Silk first for lining burrows; aerial webs came once there were flying insects worth catching.", w=1, cls=("Arachnida", "Araneae", ""))
E("Scorpiones", "order", "land", "scorpion", 340, 0, C, "Scorpions: among the first arachnids ashore, and scarcely changed in outline since the Carboniferous.", lat=[0, 50], w=1, cls=("Arachnida", "Scorpiones", ""))
E("Pulmonoscorpius", "genus", "land", "scorpion", 336, 330, ["eu"], "A 70 cm scorpion of the Scottish coal-age forests, with compound eyes and book lungs -- a land hunter, not a swimmer.", cls=("Arachnida", "Scorpiones", ""))
# ---- Triassic
E("Rauisuchia", "clade", "land", "archosaur", 250, 201, C, "Crocodile-line archosaurs that walked upright on pillar legs: the top land predators of the Triassic, before dinosaurs had the role.", rep="Postosuchus", cls=(R, "", "Rauisuchidae"))
E("Kannemeyeriiformes", "clade", "land", "dicynodont", 247, 201, C, "The big tusked dicynodonts of the Triassic -- ox-sized, beaked herbivores found on every part of Pangaea.", cls=("Synapsida", "Dicynodontia", "Kannemeyeriidae"))
E("Traversodontidae", "family", "land", "cynodont", 247, 205, ["sa-s", "af-s", "af-e", "mg", "in", "na-e", "eu"], "Plant-eating cynodonts with broad grinding cheek teeth -- the commonest herbivores of many Gondwanan Triassic faunas.", cls=("Synapsida", "Cynodontia", "Traversodontidae"))
E("Rhynchosauria", "order", "land", "rhynchosaur", 250, 225, ["sa-s", "in", "af-e", "af-s", "mg", "eu", "na-w", "na-e"], "Pig-sized reptiles with a parrot beak and shearing tooth plates. In places they are half of all the fossils found -- then gone by the Norian.", cls=(R, "Rhynchosauria", ""))
