E("Plateosauridae", "family", "land", "prosauropod", 228, 201, ["eu", "gl"], "Long-necked, bipedal plant-eaters up to ten metres: the first dinosaurs to grow large, found in herds in Late Triassic Europe.", rep="Plateosaurus", cls=(S, "Sauropodomorpha", "Plateosauridae"))
E("Massospondylidae", "family", "land", "prosauropod", 210, 183, ["af-s", "sa-s", "an", "na-w", "in", "as-e"], "Mid-sized early sauropodomorphs of Early Jurassic Gondwana and beyond; nests of Massospondylus eggs show the young hatched toothless and helpless.", cls=(S, "Sauropodomorpha", "Massospondylidae"))
E("Herrerasaurus", "genus", "land", "theropod", 233, 229, ["sa-s"], "One of the earliest dinosaurs of all: a three- to six-metre predator from Ischigualasto, when dinosaurs were still a minor part of the fauna.", w=3, cls=(S, "", "Herrerasauridae"))
E("Eoraptor", "genus", "land", "smalltheropod", 233, 229, ["sa-s"], "A metre-long, light-boned dinosaur from the dawn of the group, with teeth suited to both meat and plants.", cls=(S, "", "Eoraptor"))
E("Riojasaurus", "genus", "land", "prosauropod", 225, 215, ["sa-s"], "A heavy ten-metre sauropodomorph of Late Triassic Argentina, already walking on all fours.", cls=(S, "Sauropodomorpha", "Riojasauridae"))
